CREATE procedure [dbo].[ETL_Fact_GeneralLedger]
(
	@Type nvarchar(4000) = null
	,@ParamList nvarchar(4000) = null	
	,@ParentEventID int = null
)
as
--
-- Standardvariabler
--
declare @ProcName sysname, @TranCount int, @EventIDStack varbinary(max)
set @ProcName = app.GetObjectFullName(@@procid)
set @TranCount = @@trancount


begin try
	--------------------------------------------------------------------------
	-- Start
	--------------------------------------------------------------------------
	exec app.LogEventStart @ParentEventID = @ParentEventID, @EventIDStack = @EventIDStack output, @EventObject = @ProcName
			,@EventTitle = 'ETL Fact: ETL_Fact_GeneralLedger'
			,@Description = ''

	 
	
	--------------------------------------------------------------------------
	-- Ladda faktatabell för huvudbok
	--------------------------------------------------------------------------		
	--
	-- Iterera igenom alla konfigurerade visma-källsystem (bolag)
	--
	declare 
		@SA_SourceSystemID int		
		,@ChDt int
		,@ChTm smallint
	
	select @SA_SourceSystemID = min(SA_SourceSystemID) from [INSIKT_KUND_SA].sa.base_SourceSystem where TargetSchema = 'visma'
	while @SA_SourceSystemID is not null
		begin				
			select top 1					
				@ChDt = ChDt
				,@ChTm = ChTm
			from
				dw.fact_GeneralLedger
			where
				SA_SourceSystemID = @SA_SourceSystemID
			order by
				ChDt desc, ChTm desc	
												
			if @@ROWCOUNT = 0
				select
					@ChDt = 0
					,@ChTm = 0
	
	
	
			select
						[PostingDateID] = f.ValDt
						,[KontoID] = isnull([Konto].[KontoID], -1)
						,[GLTransactionTypeID] = 1 -- Normaltransaktion
						,[VerifikationstypID] = isnull([Verifikationstyp].[VerifikationstypID], -3)
						,[LeverantörID] = isnull([Leverantör].[LeverantörID], -5)
						,[AnläggningID] = isnull([Anläggning].[AnläggningID], -7)
						,[KundID] = isnull([Kund].[KundID], -19)
						,[AnställdID] = isnull([Anställd].[AnställdID], -10)
						,[KampanjID] = isnull([Kampanj].[KampanjID], -12)
						,[VarugruppID] = isnull([Varugrupp].[VarugruppID], -13)
						,[KassaID] = isnull([Kassa].[KassaID], -14)
						,[ProjektID] = isnull([Projekt].[ProjektID], -15)
						,[AvdelningID] = isnull([Avdelning].[AvdelningID], -16)
						,[Amount] = f.AcAm
						,[Number] = f.Qty
						,[RowTypeID] = 1 -- Huvudbokstransaktion
						,[SA_SourceSystemID] = f.SA_SourceSystemID
						,[JNo] = f.JNo
						,[EntNo] = f.EntNo
						,[VouNo] = f.VoNo
						,[ChDt] = f.ChDt
						,[ChTm] = f.ChTm
						,[Txt] = f.Txt
						,[InvoiceDocumentID] = f.WfId
						
			into #NewChangedFactData
			from
				[INSIKT_KUND_SA].visma.AcTr_Extended f
											
					left join [dw].[base_Konto] [Konto] on
						[Konto].Code = f.[AcNo]
											
					left join [dw].[base_Verifikationstyp] [Verifikationstyp] on
						[Verifikationstyp].Code = f.[VoTp]
											
					left join [dw].[base_Leverantör] [Leverantör] on
						[Leverantör].Code = f.[Sup]
											
					left join [dw].[base_Anläggning] [Anläggning] on
						[Anläggning].Code = f.[PropNo]
											
					left join [dw].[base_Kund] [Kund] on
						[Kund].Code = f.[Cust]
											
					left join [dw].[base_Anställd] [Anställd] on
						[Anställd].Code = f.[Emp]
											
					left join [dw].[base_Kampanj] [Kampanj] on
						[Kampanj].Code = f.[R6]
											
					left join [dw].[base_Varugrupp] [Varugrupp] on
						[Varugrupp].Code = f.[R4]
											
					left join [dw].[base_Kassa] [Kassa] on
						[Kassa].Code = f.[R3]
											
					left join [dw].[base_Projekt] [Projekt] on
						[Projekt].Code = f.[R2]
											
					left join [dw].[base_Avdelning] [Avdelning] on
						[Avdelning].Code = f.[R1]
												
			where
				((f.ChDt > @ChDt) or (f.ChDt = @ChDt and f.ChTm >= @ChTm))
				and f.[SA_SourceSystemID] = @SA_SourceSystemID
	
	
			--
			-- Uppdatera faktatabell med nya och ändrade rader.
			--
			exec app.SyncTable
				@SourceTable = '#NewChangedFactData'
				,@TargetTable = '[dw].[fact_GeneralLedger]'
				,@JoinColumns = '[SA_SourceSystemID], [JNo], [EntNo]'
				,@DeleteMode = 3 -- Borttagna lämnas kvar (endast insert/update)
				,@SupressWarnings = 1
			
			
			
	
			drop table #NewChangedFactData
			select @SA_SourceSystemID = min(SA_SourceSystemID) from [INSIKT_KUND_SA].sa.base_SourceSystem where TargetSchema = 'visma' and SA_SourceSystemID > @SA_SourceSystemID
		end
	--------------------------------------------------------------------------

	exec app.LogEventStop @EventIDStack = @EventIDStack out
	--------------------------------------------------------------------------
	-- Stop
	--------------------------------------------------------------------------
end try
begin catch	
	--
	-- Roll back any transactions and log errors
	--
	if @TranCount = 0 and @@trancount > 0 rollback tran
	exec app.HandleProcError @EventIDStack out, @ParentEventID, @ProcName
	exec app.ReThrowError
end catch

